   async page(offset,limit=8,permit=last?.payload.read_permit){const origin=last,r=await api.get(`/hub-device/v1/manifests/${packageRef.hub_manifest_sha256}?offset=${offset}&limit=${limit}`,{},{permit,maxBytes:4096}),v=decodeDeviceWire(r.body);need(r.status===200&&v.type==='manifest.page'&&same(v.context,context)&&v.request_id===origin.request_id&&v.request_seq===origin.request_seq&&same(v.payload.package_ref,packageRef)&&v.payload.offset===offset&&r.headers['x-round-pet-read']===permit.id,'manifest_response');return v;},
